/**
 * A context-object web framework, declared the way the real ones are
 * (carrick#964).
 *
 * The handler receives ONE context object that both reads the request and
 * sends the response, so the context carries a `body` MEMBER whose type is the
 * response sender — a callable, not a payload. Route registration threads a
 * validator middleware's schema into the context's validated-input type, so
 * `c.req.valid(target)` is the payload the middleware declared.
 */

export interface HttpResponse {
  readonly status: number;
}

/**
 * The response-body sender the context exposes as `body`. Callable, with no
 * relation whatsoever to the request contract — reading it as the request body
 * is the defect in carrick#964.
 */
export interface BodySender {
  (data: string | null, status?: number): HttpResponse;
  (data: string | null, headers?: Record<string, string>): HttpResponse;
}

export interface RequestFacade<Validated> {
  /** The payload a validator middleware declared for `target`. */
  valid<Target extends keyof Validated>(target: Target): Validated[Target];
  json(): Promise<unknown>;
  header(name: string): string | undefined;
}

export interface RouteContext<Validated> {
  /** Sends a response body. NOT the request payload. */
  body: BodySender;
  json(data: unknown, status?: number): HttpResponse;
  req: RequestFacade<Validated>;
}

export interface Middleware<Target extends string, Output> {
  readonly target: Target;
  readonly output: Output;
}

/**
 * Validator middleware: binds a schema to a named part of the request. The
 * schema is accepted structurally (anything that parses into an output), the
 * way a real validator bridge accepts any schema library.
 */
export declare function validator<Target extends string, Output>(
  target: Target,
  schema: { parse(data: unknown): Output }
): Middleware<Target, Output>;

export type Handler<Validated> = (
  c: RouteContext<Validated>
) => HttpResponse | Promise<HttpResponse>;

export declare class Router {
  post<Target extends string, Output>(
    path: string,
    middleware: Middleware<Target, Output>,
    handler: Handler<{ [K in Target]: Output }>
  ): Router;
  post(path: string, handler: Handler<Record<string, unknown>>): Router;
  get(path: string, handler: Handler<Record<string, unknown>>): Router;
}
